"""Generate the review plan, author handover and practical-experience map."""
import json
from collections import Counter
from pathlib import Path

WORK=Path(__file__).resolve().parents[1]
ROOT=WORK.parents[1]
def read(path):return json.loads(path.read_text())

def main():
    registry=read(WORK/'curriculum/objective_registry.json')['objectives']
    leaves=[o for o in registry if o['parent_id']]
    orders=[read(p) for p in sorted((WORK/'topics').glob('*/work_order.json'),key=lambda p:int(p.parent.name))]
    slots=[s for o in orders for s in o['item_slots']];tasks=[s for o in orders for s in o['performance_tasks']]
    total_items=len(slots)+len(tasks);marks=Counter()
    mc_blooms=Counter(p['blooms_level'] for t in tasks if t['item_type']=='multiple_choice_set' for p in t['parts'])
    for o in orders:marks.update(o['planned_ao_marks'])
    total_marks=sum(marks.values());recall=[s for s in slots if s['subtype'] in ['DEF','FEATURE']]
    recall_marks=sum(s['mark_tariff'] for s in recall)
    embedded_recall=sum(p['mark_tariff'] for t in tasks for p in t['parts'] if p['blooms_level']=='Remember')
    budget=[read(WORK/'topics'/o['topic_id']/'contract.json')['depth_constraints']['word_budget'] for o in orders]
    practicals=read(WORK/'curriculum/syllabus-outcomes.json')['suggested_practicals']
    # Semantic teaching links for every suggested practical, in syllabus order.
    subtopics=['1.5','1.5','1.5','1.5','2.1.1','2.1.1','2.4.1','2.3.3','2.3.3','2.3.3','8.2','8.1','2.3.3','2.3.3','2.3.3','2.4.1','2.4.3','2.4.5',
      '3.2','3.2','3.2','3.3','3.3','5.1','5.1','6.2','6.4','6.5','6.4','6.2','7.1','7.1','7.3','7.4','7.3','7.3','7.4','8.2','8.1','8.1','8.2','9.2','9.2','1.5','3.3','10.4','10.8.3','11.5','11.1.1','11.1.2','11.2','10.5','11.1.2','11.1.2','11.1.2']
    assert len(practicals)==len(subtopics)==55
    mapped=[]
    for p,sub in zip(practicals,subtopics):
        content=[o['objective_id'] for o in leaves if o['sub_topic']==sub]
        assert content,(p,sub)
        text=p['text'].lower()
        skill=['12.5-01','12.1-01','12.4-01'] if 'design' in text else ['12.6-01','12.3-02'] if 'test' in text or 'identif' in text else ['12.2-01','12.2-03','12.3-01']
        mapped.append(p|{'content_objective_ids':content,'practical_skill_objective_ids':['OBJ-6117-'+s for s in skill],
          'delivery':'A dedicated original teaching-note experience box in its syllabus content topic, cross-linked from topic 12.',
          'required_outputs':['aim and apparatus','safe supervised method outline','expected observations or clearly labelled invented practice data','model explanation and interpretation','relevant control or limitation'],
          'mapping_basis':'planning judgement by the stated practical purpose; not a counted exam-frequency mapping'})
    write=WORK/'planning/practical-experiences.json';write.write_text(json.dumps({'status':'required_teaching_experiences','count':55,'experiences':mapped},indent=2,ensure_ascii=False)+'\n')
    frameworks=read(WORK/'curriculum/assessment-framework.json')
    bodies=['# Plan — NSSCO Chemistry 6117','',
      'Generated from the approved Step 3 evidence and the Step 4 planning inputs. **Step 4 approved by the user on 2026-10-26. Production-stage prototype review remains required.** This document is regenerated by `planning/render_plan.py`.',
      '', '## 0. What the syllabus says','',
      'Authority: the 2018 NSSCO Chemistry 6117 syllabus, first examined in 2020. The route includes Papers 1, 2 and 3. Step 3 was explicitly approved by the user in this conversation.',
      '', '| AO | Name | Approximate qualification weight |','|---|---|---:|']
    for ao in frameworks['assessment_objectives']:bodies.append(f"| {ao['code']} | {ao['name']} | {ao['qualification_weight_percent']}% |")
    bodies+=['','**Recall ceiling: not more than 25% of qualification marks.** AO A includes knowledge with understanding; it is not all pure recall. Source: printed pp.38–40 / PDF pp.41–43.','',
      '| Paper | Marks | Syllabus duration | Qualification weight |','|---|---:|---:|---:|']
    for p in frameworks['papers']:bodies.append(f"| {p['paper']} — {p['name']} | {p['marks']} | {p['duration_minutes']} minutes | {p['weight_percent']}% |")
    bodies+=['','The 2025 Paper 1 specifies 1 hour; the syllabus specifies 45 minutes. Use **45 minutes** for Paper 1. Paper 2 comprises compulsory short-answer, structured and free-response questions.',
      '', '## 1. What the corpus says','',
      'The approved corpus contains 18 papers and six examiner reports for 2020–2025: 691 paper records and 960 raw marks, plus 34 examiner findings and 19 curated misconceptions. Reports are the available answer/marking source.',
      'The 299 internal answer rows must be independently reworded and recalculated before learner use. The five 2022 Paper 2 Q3 commentary-only parts must not be given invented official allocations. The 2022/2023 papers retain their first/revised-proof caveat.',
      '', '## 2. Command words and tariffs','',
      'Registry commands are extracted from each objective’s own opening wording. A secondary task may use another observed command where its task shape requires it; its reason must say so. In particular, a Define objective receives a Define anchor rather than a family-wide State default.',
      'Ordinary slots use the observed modal tariff. Three-mark stoichiometry variants deliberately model observed staged Calculate questions. Every slot records `tariff_provenance`, including example evidence IDs and the reason for any departure from the modal value.',
      f"MC part Bloom counts (provisional): {', '.join(f'{k} {v}' for k,v in sorted(mc_blooms.items()))}. Each must be checked against the final stem and options.",
      'The work order fixes written-response commands and tariffs. All 132 multiple-choice parts have a null command word and one mark; their provisional Bloom labels follow the named objective and an explicit cognitive-demand brief, not their position in the set. Generic Use/Which/What openings are not enabled as standalone flashcard commands. See the approved analysis for unused glossary entries and observed commands absent from the glossary.',
      '', '## 3. Answer shapes','',
      'Card slots carry objective-linked answer-shape templates, scope/variant and an allocation rule. Most templates are not completed credit points: the author must supply the original stimulus, answer and explicit credited elements, especially for APP and INTERP. The 32 Topic 4 calculation variants have fixed checked answers; activity parts have more specific credit briefs, while MC keys and distractors remain to be authored. Machine keyword checks remain a separate structural aid and do not substitute for an answer rubric. Drawing tasks use the supported APP subtype with `representation_task: true`, a Draw/Sketch command and required visuals; DIAGRAM is not a supported learner-item subtype.',
      'The 32 Topic 4 calculation cards fix original givens, the required unknown and a checked answer. Variants include direct/reverse calculations, unit conversion, reacting ratios, limiting reagent, empirical/molecular formula, percentage composition/yield/purity. The cm³-to-dm³ diagnostic variant cites ER-6117-2022-19.',
      'Each performance task fixes objective IDs, paper, context, subpart commands, tariffs, AO/Bloom labels, answer requirements and visuals. Six-mark investigation rubrics must separately allocate setup, controls, measurements and conclusion; graph rubrics separate plotting, curve and read-off credit.',
      '', '## 4. Card types, assessment objectives and Bloom levels','',
      '| Subtype | Planned cards | Main demand |','|---|---:|---|']
    counts=Counter(s['subtype'] for s in slots)
    meanings={'DEF':'Precise identity or meaning','FEATURE':'Named properties or observations','MECH':'Chemical relationship or mechanism','PROC':'Ordered method or sequence','APP':'Application or constructing a representation','INTERP':'Interpret supplied evidence','CALC':'Numerical method and result','DIAGRAM':'Construct a labelled representation','DIST':'Discriminate related ideas','LIM':'Limitation and consequence','MISCON':'Diagnose a report-evidenced confusion'}
    for st,n in sorted(counts.items()):bodies.append(f'| {st} | {n} | {meanings[st]} |')
    bodies+=['',f'Pure-recall proxy (DEF + FEATURE): **{len(recall)} of {total_items} top-level items ({100*len(recall)/total_items:.1f}%)**. By marks those cards contribute **{recall_marks:g}/{total_marks:g} ({100*recall_marks/total_marks:.1f}%)**. Including all Remember-labelled subparts within activities gives **{recall_marks+embedded_recall:g}/{total_marks:g} ({100*(recall_marks+embedded_recall)/total_marks:.1f}%)**.',
      'The item fraction exceeds 25%, but the syllabus ceiling is a share of marks. The mark-based proxy remains below it. These figures are planning estimates; recheck actual prompts during authoring, since a subtype or Bloom label alone cannot establish cognitive demand. Trigger: recompute subject-wide pure-recall marks across all cards and activity parts after each authored topic. No per-topic recall ceiling or publication hold applies; factual topics can exceed 25% locally. Use the complete subject marks denominator, not only cards or a single topic. Use 24% as the subject warning threshold to retain headroom; exceeding 25% blocks publication. The 24% warning is our operational rule; the 25% ceiling is the syllabus requirement.',
      '', '## 5. The topics','',
      '**Topic 12 is our teaching organisation, not a twelfth syllabus content topic.** It draws on AO C1–C5 (PDF pp.41–42), Annexe A experimental requirements (PDF p.47) and apparatus guidance (p.48). The 55 syllabus suggested practicals are individually mapped in `planning/practical-experiences.json`: each has a content-topic experience box and explicit topic-12 skill links.',
      '', '| Topic | Assessable objectives | Cards | Activities | Total items | Notes words |','|---|---:|---:|---:|---:|---:|']
    for o,b in zip(orders,budget):bodies.append(f"| {o['topic_id']} {o['topic_title']} | {o['assessable_objective_count']} | {len(o['item_slots'])} | {len(o['performance_tasks'])} | {o['planned_item_count']} | {b['min']:,}–{b['max']:,} |")
    bodies += [f"| **Total** | **{len(leaves)}** | **{len(slots)}** | **{len(tasks)}** | **{total_items}** | **{sum(b['min'] for b in budget):,}–{sum(b['max'] for b in budget):,}** |",'',
      'Activity inventory: '+', '.join(f'{n} {kind.replace("_"," ")}' for kind,n in Counter(t['item_type'] for t in tasks).items())+'. Multiple-choice sets contain 12 questions each; sets count as one top-level activity, so their question count is reported separately.',
      'Every suggested practical receives a teaching box; these 55 boxes are not additional exam-marked activities and have no invented examination allocation.',
      '', '## 6. AO balance, in marks','', '| AO | Planned marks-equivalent | Planned share | Syllabus target | Gap |','|---|---:|---:|---:|---:|']
    for ao,target in [('A',50),('B',30),('C',20)]:bodies.append(f'| {ao} | {marks[ao]:g} | {100*marks[ao]/total_marks:.2f}% | {target}% | {100*marks[ao]/total_marks-target:+.2f} points |')
    bodies+=['','No balancing top-up cards were added. Differences reflect the full syllabus and explicit practical teaching, with a largest gap of '+f"{max(abs(100*marks[a]/total_marks-v) for a,v in [('A',50),('B',30),('C',20)]):.2f} percentage points.",
      '', 'AO labels for activity parts now follow their explicit cognitive demands, independently of part position. MC selection does not filter by an intended AO quota. A remains above 50% and B below 30% because full-coverage definition, description and familiar-explanation practice dominates the current card inventory, and familiar-concept MC questions are A. This is a disclosed practice-bank imbalance, not an exam blueprint; assembled mock papers must follow the syllabus component weights. No padding or relabelling was used to conceal it.',
      '', '### Emphasis compared with observed content-paper exposure','',
      'The table compares only planned A+B marks with observed Paper 1+2 shares, and separately shows planned C marks. It does not compare the whole practical-inclusive portfolio with content-only papers.',
      '', '| Topic | Planned A+B share | Observed P1+P2 share | Planned C marks |','|---|---:|---:|---:|']
    observed={str(t['topic']):t['share_percent'] for t in read(WORK/'curriculum/topic-context-exposure.json')['topics']}
    content=sum(marks[a] for a in ['A','B'])
    for o in orders:
        m=o['planned_ao_marks'];bodies.append(f"| {o['topic_id']} {o['topic_title']} | {100*(m.get('A',0)+m.get('B',0))/content:.1f}% | {observed.get(o['topic_id'],'—')}"+('%' if o['topic_id'] in observed else '')+f" | {m.get('C',0):g} |")
    bodies+=['','Topics 1 and 8 contain substantial experimental and qualitative work that is not represented by their small Paper 1+2 shares. Their C practice and topic 12 are deliberate. Stoichiometry has been expanded to 32 distinct calculation cards plus a five-mark calculation activity and titration/data work. Every topic retains full mandatory coverage; observed frequency calibrates examples and variants rather than removing objectives.',
      'Individual-outcome exam frequencies remain **unmeasured**. The approved subtopic and practical-criterion exposure counts are preserved; the plan does not copy a subtopic count onto each child objective.',
      '', '## 7. Misconceptions, glossary and scope','',
      'All 19 curated misconceptions have a named MISCON slot and diagnostic. The conversion omission is addressed by a specific Topic 4 calculation variant without reclassifying every procedural omission as a misconception.',
      'The glossary settles recurring chemistry meanings. Each topic contract includes all 12 explicit scope guards. Qualitative wet cation/anion tests are confined to Paper 3; flame and gas tests may occur on all three papers. Annexe B notes are not supplied in the examination.',
      '', '## 8. Rules particular to this subject','',
      '1. Author original examples, answers and diagrams. Internal examiner-report answers are evidence, not learner-ready wording.',
      '2. Independently recalculate every numerical answer, including the known 2025 report discrepancy.',
      '3. Keep precipitate, solution, observation and inference distinct. Specify electrode and electrolyte conditions in electrolysis.',
      '4. Supply all apparatus/graph data and readable visuals in the item. A request to draw does not replace a needed reference figure.',
      '5. Preserve the five commentary-only evidence gaps without inventing official allocations.',
      '6. Use 45 minutes for Paper 1; retain the proof-version caveat.',
      '7. Every final item carries its work-order ID, AO, Bloom level, command and tariff; every change must be recorded.',
      '', '### Build and review','',
      'Regenerate with the workspace planning scripts: `extract_learning_outcomes.py`, `build_plan_inputs.py`, `build_resource_plan.py`, then `render_plan.py`, using the repository `.venv/bin/python`. The wrapper calls the repository contract/work-order generators, merges the documented slot-plan extension in memory and uses a conservative unmeasured-exposure budget; it changes no files under `standard/`.',
      'The user approved Step 4 on 2026-10-26; the production-stage prototype checkpoint remains open. Before Step 5, human semantic review must cover all 56 calculation-card specifications and all 36 activity specifications: objective alignment, sufficient givens, achievable demand, answers where specified and credit allocation. Confirmation of the 32 Topic 4 answers and two calculation-activity answers does not close this wider gate. Review each VIS specification separately for scientific and numerical validity; recheck the rendered assets after authoring. The gate also requires human review of nine fully authored prototype cards: DEF, FEATURE, MECH, APP, INTERP, PROC and MISCON samples plus the two existing calculation exemplars. Required IDs are recorded in `planning/semantic-review-gate.json`; prototypes precede full Step 5 production. Record reviewer, date, reviewed IDs and resolved findings there. Authoring follows explicit plan approval and closure of this gate; failed checks must be repaired and rerun, then an independent reviewer checks the resources.',
      '', '### Activity specifications','', 'Paper 2 practice now includes three free-response tasks (Topics 3, 7 and 11), presented without lettered scaffolding; internal credit groups are for marking only. Other tasks vary from six to nine marks. These compact practice questions do not reproduce the full observed 6–20-mark range. Paper 3 tasks are 12 marks, except the expanded electrode investigation at 15 marks. All investigation-design parts use Plan; the titration part explicitly requests both titre and amount.', '', '| Slot | Type | Paper | Marks | Objectives fixed | Context / purpose |','|---|---|---:|---:|---:|---|']
    for t in tasks:bodies.append(f"| {t['slot']} | {t['item_type']} | {t['paper_id']} | {t['mark_tariff']} | {len(t['objective_ids'])} | {t.get('context_brief',t['brief']).replace('|','/')} |")
    bodies += ['', '### Review files and validation limits', '', '[Detailed activity briefs](ACTIVITY-SPECIFICATIONS-6117-nssco-chemistry.md) give every part’s objective IDs, command, tariff, AO/Bloom labels, credit points and required visuals. [Plan validation](planning/plan-validation.json) recomputes coverage, commands/tariffs, counts, source lines, recall and AO balance. [Exemplar validation](exemplar/validation-summary.json) records the actual check outcomes.', '', '[Visual drawing briefs](VISUAL-SPECIFICATIONS-6117-nssco-chemistry.md) specify all 35 VIS entries: labels, geometry/values, acceptance criteria and learner/answer separation. Every practical activity includes its original stimulus, expected answers, tolerances and apparatus labels in the detailed activity briefs. These specifications still require human scientific review.', '', 'The concentration exemplar has no failed checks, one expected single-skill AO warning and three inapplicable checks (graphs, generated depictions and practice texts). It is structural evidence, not semantic approval of the whole bank. The standard chart model only handles business break-even; Chemistry visuals require separate scientific/numerical review. The Chemistry check adapter supplies conditional-mechanism rules in memory because the canonical profile schema omits that runtime field. No standard files were changed.', '', 'All 309 retained syllabus outcome source lines were found on their exact cited pages. This verifies location, not every decomposition or interpretation. Individual-outcome exam exposure remains unmeasured. Step 4 approval is recorded; the authored-prototype review is a separate production checkpoint.']
    detail=['# Activity specifications — NSSCO Chemistry 6117', '', 'Part-level planning briefs for review. These are original authoring specifications, not reproduced official questions or official mark allocations. The final author must realise these briefs in self-contained questions and answers.', '']
    for t in tasks:
        detail += [f"## {t['slot']} — {t['item_type']}", '', t['context_brief'], '', f"Paper {t['paper_id']}; {t['mark_tariff']} marks; AO split: {t['ao_split']}.", '', 'Required visuals: '+(', '.join(t.get('required_visual_ids',[])) or 'None; supply any stimulus data within the question.'), '']
        if t.get('free_response_prompt'):detail += ['Learner prompt: '+t['free_response_prompt'], '', t['learner_presentation'], '']
        if t.get('stimulus_specification'):
            detail += ['Stimulus, expected results and tolerances (original synthetic data):', '', '```json', json.dumps(t['stimulus_specification'],indent=2,ensure_ascii=False), '```', '']
        detail += ['| Part | Command | Marks | AO / Bloom | Assessed objectives | Credit requirements |', '|---|---|---:|---|---|---|']
        for part in t['parts']:
            detail.append(f"| {part['part']} | {part['command_word'] or '— (MC)'} | {part['mark_tariff']} | {','.join(part['assessment_objectives'])} / {part['blooms_level']} | {', '.join(part['objective_ids'])} | {(part.get('planned_cognitive_demand','')+' '+part['credit_requirement']).strip().replace('|','/')} |")
        detail.append('')
    vdoc=['# Visual specifications — Chemistry 6117', '', 'Original drawing briefs, pending scientific and numerical review. Do not put keyed answers in learner stimuli.', '']
    for v in read(WORK/'planning/visual-manifest.json')['visuals']:
        vdoc += [f"## {v['visual_id']} — {v['purpose']}", '', '**Labels:** '+', '.join(v['required_labels']), '', '**Geometry and values:** '+v['geometry_and_values'], '', '**Acceptance:** '+v['scientific_acceptance_criteria'], '', v['learner_answer_separation'], '']
    (WORK/'VISUAL-SPECIFICATIONS-6117-nssco-chemistry.md').write_text('\n'.join(vdoc)+'\n')
    (WORK/'ACTIVITY-SPECIFICATIONS-6117-nssco-chemistry.md').write_text('\n'.join(detail)+'\n')
    (WORK/'PLAN-6117-nssco-chemistry.md').write_text('\n'.join(bodies)+'\n')
    handover=f'''# Handover — NSSCO Chemistry 6117

Read AGENTS.md and the author role brief. Work only in `work/nam-6117-nssco-2026/` after the user approves Step 4.

## Entry gate

Before Step 5, the human reviewer must sign off all 56 calculation-card specifications, all 36 activities and the scientific/numerical VIS specifications in planning/semantic-review-gate.json, then approve the plan. The gate also covers nine fully authored sample cards (seven specified non-calculation slots and the two calculation exemplars). Write the prototypes before full production; templates alone cannot establish correctness. Structural check success does not close this gate. Final authored answers and rendered visuals require review again before publication.

## The job

Author {len(slots)} flashcards and {len(tasks)} performance activities across 12 teaching topics. Teach all {len(leaves)} assessable targets in {sum(b['min'] for b in budget):,}–{sum(b['max'] for b in budget):,} words of standalone notes. Topic 12 organises Annexe A practical skills; it is not extra syllabus content.

For every topic, read its generated contract and work_order.json. The work order fixes each slot and every activity subpart, target, tariff, answer requirement and visual. Create the claim ledger, content-unit JSON and learning-items JSON, then render notes with the repository renderer. The visual-manifest lists the required SVG assets. The practical-experiences map fixes all 55 original teaching boxes and their content/skill links.

## Every item carries its labels

Copy slot ID, subtype/type, objective IDs, assessment objectives, Bloom level, command and tariff. Use variant_spec and the answer-shape templates. Write the actual stimulus, answer and credit points; do not present the template as a finished rubric. Multiple-choice parts have command_word null; confirm their provisional Bloom labels against the authored stem and options. Performance parts must sum to the declared total and preserve their AO split. Record any deviation instead of silently redesigning a slot.

## Rules from the syllabus and corpus

- Use newly written prompts, answers and visuals. Reword and independently check all internal report-derived material.
- The 299 internal report rows need fresh wording and verified arithmetic. The five commentary-only parts have no invented official allocations.
- Use 45 minutes for Paper 1 and retain the first/revised-proof caveat for 2022/2023 sources.
- Wet ion tests belong only to Paper 3; gas/flame tests can occur on all papers. Teach their observations without relying on supplied Annexe B notes.
- Mark investigation plans by setup, controls, measurement and conclusion. Mark graph plotting, curve and read-off separately.
- Supply realistic original data; recompute values and state units. Use the fixed calculation variants rather than cloning cards.
- The recall ceiling concerns marks. Audit actual demand after each topic. There is no per-topic recall cap. Subject recall above 24% triggers review, and above 25% blocks publication. Include activity subparts in the subject denominator.
- Follow the contract scope guards and glossary. Do not introduce orbital chemistry, gas-law conversions or out-of-scope reaction mechanisms.

## Build and checks

Use `.venv/bin/python standard/v0.2.0-draft/build/render_notes.py work/nam-6117-nssco-2026 <topic>`, followed by `.venv/bin/python work/nam-6117-nssco-2026/planning/check_resource_topic.py <topic>`. Use `checks/what_to_fix.py` under the standard folder to inspect the resulting failures. Repair failures and rerun. When complete, obtain independent review, fix findings and rerun checks before publishing. Do not commit or push.

## Plan dependencies

The command framework comes from the corrected Step 3 audit. Leaf exposure is deliberately unmeasured; do not invent frequency counts. Generator settings are in planning/slot-plan.json and applied by planning/build_resource_plan.py without modifying the standard. The structural exemplar is a small internal guide, not published learner output. Its checked scope is one concentration objective, two cards and one calculation. It is not an exemplar for every activity or visual type.

Use `planning/check_resource_topic.py <topic>` for the unchanged standard suite with Chemistry runtime extensions loaded in memory. The canonical profile schema does not accept conditioned_mechanisms or depictions; this adapter supplies them without editing standard/. Chemistry graphs require separate numerical/visual checks because the standard chart checker only models business break-even. The standard CLI reports PUBLISH but returns exit code 1 (it tests for pass); inspect check statuses or use this adapter, which fails on failed checks.
'''
    (WORK/'HANDOVER-6117-nssco-chemistry.md').write_text(handover)
    print('Rendered plan and handover:',total_items,'items;',len(practicals),'practical experience mappings')

if __name__=='__main__':main()
